//! Fetchly — a fast, cross-platform API client built with Dioxus.
#![cfg_attr(all(not(debug_assertions), target_os = "windows"), windows_subsystem = "windows")]

mod actions;
mod components;
mod highlight;
mod platform;
mod store;
mod ui;

use dioxus::prelude::*;
use store::*;
use ui::chrome::{Console, Footer, Header, TabBar, Toasts};
use ui::dialogs::Dialogs;
use ui::editor::RequestEditor;
use ui::response::ResponsePane;
use ui::sidebar::Sidebar;

/// Brand icons (data URLs), generated by build.rs from `assets/brand/`.
pub mod brand {
    include!(concat!(env!("OUT_DIR"), "/brand.rs"));
}

const FONTS_CSS: &str = include_str!(concat!(env!("OUT_DIR"), "/fonts.css"));
const COMPONENTS_CSS: &str = include_str!("../styles/components.css");
const APP_CSS: &str = include_str!("../styles/app.css");
/// Inlined on desktop so dialogs keep their focus trap without a bundled asset directory.
#[cfg(feature = "desktop")]
const FOCUS_TRAP_JS: &str = include_str!("../assets/js/focus-trap.js");

fn main() {
    let first_run = store::init();
    FIRST_RUN.with(|f| f.set(first_run));

    #[cfg(feature = "desktop")]
    {
        use dioxus::desktop::{Config, LogicalSize, WindowBuilder};
        let icon = {
            let rgba = include_bytes!(concat!(env!("OUT_DIR"), "/window-icon.rgba")).to_vec();
            let size: u32 = include_str!(concat!(env!("OUT_DIR"), "/window-icon.size")).parse().unwrap_or(256);
            dioxus::desktop::tao::window::Icon::from_rgba(rgba, size, size).ok()
        };
        let mut cfg = Config::new()
            .with_window(
                WindowBuilder::new()
                    .with_title("Fetchly")
                    .with_inner_size(LogicalSize::new(1400.0, 880.0))
                    .with_min_inner_size(LogicalSize::new(960.0, 600.0)),
            )
            // Let HTML5 drag-and-drop reach the page (needed for sidebar reordering on Windows).
            .with_disable_drag_drop_handler(true)
            .with_background_color((9, 9, 11, 255))
            .with_custom_head(format!("<meta name=\"color-scheme\" content=\"light dark\"><script>{FOCUS_TRAP_JS}</script>"))
            .with_menu(default_menu());
        if let Some(icon) = icon {
            cfg = cfg.with_icon(icon);
        }
        dioxus::LaunchBuilder::desktop().with_cfg(cfg).launch(App);
    }
    #[cfg(not(feature = "desktop"))]
    dioxus::launch(App);
}

#[cfg(feature = "desktop")]
fn default_menu() -> dioxus::desktop::muda::Menu {
    use dioxus::desktop::muda::{Menu, PredefinedMenuItem, Submenu};
    let menu = Menu::new();
    #[cfg(target_os = "macos")]
    {
        let app = Submenu::new("Fetchly", true);
        let _ = app.append_items(&[
            &PredefinedMenuItem::about(Some("About Fetchly"), None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::hide(None),
            &PredefinedMenuItem::hide_others(None),
            &PredefinedMenuItem::show_all(None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::quit(None),
        ]);
        let _ = menu.append(&app);
    }
    let edit = Submenu::new("Edit", true);
    let _ = edit.append_items(&[
        &PredefinedMenuItem::undo(None),
        &PredefinedMenuItem::redo(None),
        &PredefinedMenuItem::separator(),
        &PredefinedMenuItem::cut(None),
        &PredefinedMenuItem::copy(None),
        &PredefinedMenuItem::paste(None),
        &PredefinedMenuItem::select_all(None),
    ]);
    let _ = menu.append(&edit);
    let window = Submenu::new("Window", true);
    let _ = window.append_items(&[&PredefinedMenuItem::minimize(None), &PredefinedMenuItem::maximize(None), &PredefinedMenuItem::fullscreen(None)]);
    let _ = menu.append(&window);
    menu
}

thread_local! {
    static FIRST_RUN: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

#[derive(Clone, Copy, PartialEq)]
enum Drag {
    Sidebar,
    Split,
}

#[component]
fn App() -> Element {
    // Theme + zoom
    use_effect(move || {
        let s = SETTINGS.read();
        let theme = match s.theme {
            ThemeChoice::System => "",
            ThemeChoice::Dark => "dark",
            ThemeChoice::Light => "light",
        };
        let zoom = s.zoom;
        document::eval(&format!(
            "const r = document.documentElement; if ('{theme}') r.setAttribute('data-theme', '{theme}'); else r.removeAttribute('data-theme'); document.body.style.zoom = '{zoom}';"
        ));
    });
    // Global keyboard shortcuts, listened for on the document so they work whatever has focus.
    use_hook(|| {
        spawn(async move {
            let mut eval = document::eval(
                r#"document.addEventListener('keydown', (e) => {
                    if (!(e.metaKey || e.ctrlKey) || e.altKey) return;
                    const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
                    if (['Enter', 's', 't', 'o'].includes(k)) {
                        e.preventDefault();
                        dioxus.send(k);
                    }
                }, true);"#,
            );
            while let Ok(key) = eval.recv::<String>().await {
                let active = ACTIVE.read().clone();
                match key.as_str() {
                    "Enter" => actions::send(active),
                    "s" => save_tab(&active),
                    "t" => new_tab(),
                    "o" => open_dialog(Dialog::Import),
                    _ => {}
                }
            }
        });
    });
    // Welcome toast + autosave
    use_hook(|| {
        if FIRST_RUN.with(|f| f.get()) {
            toast("Welcome to Fetchly! Open “Sample APIs” in the sidebar to get started.");
        }
        spawn(async move {
            let mut last = String::new();
            loop {
                platform::sleep_ms(1500).await;
                let s = snapshot();
                if s != last {
                    platform::save_state(&s);
                    last = s;
                }
            }
        });
    });

    let mut drag = use_signal(|| None::<Drag>);
    let mut main_height = use_signal(|| 600.0f64);
    let show_console = UI.read().show_console;
    let split = UI.read().split;

    rsx! {
        document::Title { "Fetchly" }
        document::Link { rel: "icon", r#type: "image/png", href: brand::FAVICON }
        document::Style { {FONTS_CSS} }
        document::Style { {COMPONENTS_CSS} }
        document::Style { {APP_CSS} }
        div {
            // Deliberately not focusable: WebKit moves focus to the nearest focusable ancestor
            // when a button is clicked, which made open dialogs think focus had left them.
            class: "app",
            onmousemove: move |e| {
                if let Some(d) = drag() {
                    let p = e.client_coordinates();
                    match d {
                        Drag::Sidebar => SETTINGS.write().sidebar_width = (p.x as f32).clamp(220.0, 560.0),
                        Drag::Split => {
                            let top = 48.0 + 38.0;
                            let frac = ((p.y - top) / main_height()).clamp(0.18, 0.82);
                            UI.write().split = frac as f32;
                        }
                    }
                }
            },
            onmouseup: move |_| drag.set(None),
            onmouseleave: move |_| drag.set(None),
            style: if drag().is_some() { "user-select: none; cursor: {if drag() == Some(Drag::Sidebar) { \"col-resize\" } else { \"row-resize\" }}" } else { "" },
            Header {}
            div { class: "app-body",
                Sidebar {}
                div { class: if drag() == Some(Drag::Sidebar) { "resizer active" } else { "resizer" }, onmousedown: move |e| { e.prevent_default(); drag.set(Some(Drag::Sidebar)); } }
                main { class: "main",
                    TabBar {}
                    div {
                        class: "col",
                        style: "flex: 1; min-height: 0; gap: 0",
                        onmounted: move |e| async move {
                            if let Ok(r) = e.get_client_rect().await {
                                main_height.set(r.height());
                            }
                        },
                        onresize: move |e| {
                            if let Ok(size) = e.get_border_box_size() {
                                main_height.set(size.height);
                            }
                        },
                        div { class: "editor", style: "height: {split * 100.0}%", RequestEditor {} }
                        div { class: if drag() == Some(Drag::Split) { "hresizer active" } else { "hresizer" }, onmousedown: move |e| { e.prevent_default(); drag.set(Some(Drag::Split)); } }
                        ResponsePane {}
                    }
                }
            }
            if show_console { Console {} }
            Footer {}
            Dialogs {}
            Toasts {}
        }
    }
}
